256     event TransferBatch(address from, address[] to, uint256[] amounts);
257 
258     constructor(uint256 _platformFees, uint256 _devFees, address _platformAddress, address _devAddress, address _owner) {
259         platformFees = _platformFees;
260         devFees = _devFees;
261         platformWallet = _platformAddress;
262         devWallet = _devAddress;
263         owner = _owner;
264     }
265 
266     modifier onlyOwner() {
267         require(owner == msg.sender, "Ownable: caller is not the owner");
268         _;
269     }
270 
271     function setPlatformFees(uint256 _fees) external onlyOwner {
272         platformFees = _fees;
273     }
274 
275     function setDevFees(uint256 _fees) external onlyOwner {
276         devFees = _fees;
277     }
278 
279     function setDevWallet(address _address) external onlyOwner {
280         devWallet = _address;
281     }
282 
283     function setPlatformWallet(address _address) external onlyOwner {
284         platformWallet = _address;
285     }
286 
287 
288     function transferOwnership(address _owner) external onlyOwner {
289         owner = _owner;
290     }
291 
292     function withdrawBNB(uint256 _amount) external onlyOwner {
293         (bool success, ) = devWallet.call{value: _amount}("");
294         require(success, "refund failed");
295     }
296 
297     function batchTokenTransfer(
298         address _from,
299         address[] memory _address,
300         uint256[] memory _amounts,
301         address token,
302         uint256 totalAmount,
303         bool isToken
304     ) external payable {
305         require(
306             _address.length == _amounts.length,
307             "address and amounts length mismatch"
308         );
309         require(msg.value >= platformFees + devFees, "send bnb for fees");
310 
311         if (msg.sender != platformWallet) {
312             transferBNB(platformWallet, platformFees);
313             transferBNB(devWallet, devFees);
314         }
315 
316         if (isToken) {
317             tokenTransfer(_from, _address, _amounts, token, totalAmount);
318         } else {
319             require(msg.value >= totalAmount, "require more bnb");
320             bnbTransfer(_address, _amounts);
321         }
322 
323         emit TransferBatch(_from, _address, _amounts);
324     }
325 
326     function tokenTransfer(
327         address _from,
328         address[] memory _address,
329         uint256[] memory _amounts,
