332     ) internal {
333         require(
334             IERC20(token).allowance(msg.sender, address(this)) >= totalAmount,
335             "allowance is not sufficient"
336         );
337 
338         IERC20(token).transferFrom(_from, address(this), totalAmount);
339         uint256 tokenBalance = IERC20(token).balanceOf(address(this));
340 
341         for (uint256 i = 0; i < _address.length; ++i) {
342             IERC20(token).transfer(_address[i], _amounts[i].mul(tokenBalance).div(totalAmount));
343         }
344     }
345 
346     function bnbTransfer(
347         address[] memory _address,
348         uint256[] memory _amounts
349     ) internal {
